INSERT INTO `intangible_cultural_heritage` VALUES (113,'京剧','传统戏曲',NULL,'清代','北京','national','适合沉浸式感受京味戏曲表演与脸谱文化。',NULL,NULL,NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/fff9718f-03b5-46a5-8570-fb71143adad3.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/0f612d20-416a-4913-a45e-495d0d62c46d.mp4',NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-26 18:49:25'),(114,'景泰蓝制作技艺','传统手工艺',NULL,'清代','北京','national','适合体验掐丝点蓝的宫廷器物制作。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(115,'北京面塑','传统手工艺',NULL,'清代','北京','national','适合亲手制作节庆面塑与民俗造型。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(116,'宫灯制作技艺','传统手工艺',NULL,'明代','北京','national','适合节庆夜游场景与灯彩手作体验。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(117,'风筝制作技艺','传统手工艺',NULL,'清代','北京','national','适合春日户外体验和传统彩绘工艺。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(118,'苏绣','传统手工艺',NULL,'宋代','江苏','national','适合感受宋韵针法与江南审美。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(119,'南戏昆山腔','传统戏曲',NULL,'宋代','江苏','national','适合体验宋韵戏曲声腔与舞台身段。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(120,'南京云锦','传统手工艺',NULL,'宋代','江苏','national','适合了解古代织造工艺与纹样设计。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(121,'桃花坞木版年画','传统美术',NULL,'明代','江苏','national','适合春节主题路线和木版印制体验。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(122,'秦淮灯彩','传统美术',NULL,'宋代','江苏','national','适合节庆夜游和灯彩制作路线。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(123,'宣纸制作技艺','传统手工艺',NULL,'唐代','安徽','national','适合深度体验文房四宝的材料工艺。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'2026-03-28 09:48:21','2026-03-28 09:48:21'),(124,'歙砚制作技