INSERT INTO `knowledge_conversations` VALUES (2,10011,'中国非遗代表','党的女儿什么时候产生的','2026-04-25 21:13:37','2026-04-25 21:05:17','2026-04-25 21:13:37'),(3,10000,'非遗云肩古时候用作什么的','云肩起源于哪里','2026-04-26 12:29:27','2026-04-26 12:26:59','2026-04-26 12:29:27');
