/*!40000 ALTER TABLE `knowledge_messages` DISABLE KEYS */;
INSERT INTO `knowledge_messages` VALUES (1,2,'中国非遗代表',1,'2026-04-25 21:05:17'),(2,2,'中国非物质文化遗产代表性项目众多，包括京剧、昆曲、书法、剪纸、端午节、皮影戏等。这些项目体现了中华民族的智慧与创造力，涵盖表演艺术、传统技艺、节庆习俗等多个领域。目前，中国已有43个项目列入联合国教科文组织非遗名录，数量居世界首位。',0,'2026-04-25 21:05:19'),(3,2,'京剧代表人',1,'2026-04-25 21:05:42'),(4,2,'京剧的代表人物包括梅兰芳、程砚秋、尚小云、荀慧生，他们被誉为“四大名旦”，以旦角表演闻名。此外，还有谭鑫培、马连良等老生名家，以及周信芳等艺术家。这些人物对京剧的唱腔、表演和传承做出了重要贡献。',0,'2026-04-25 21:05:44'),(5,2,'当代的艺术家呢',1,'2026-04-25 21:06:04'),(6,2,'当代京剧艺术家包括于魁智、李胜素、张火丁、王珮瑜等。于魁智以老生唱腔见长，李胜素是梅派青衣代表人物，张火丁专攻程派艺术，王珮瑜则致力于余派老生传承。他们活跃在舞台和教学领域，推动京剧在新时代的创新与传播。',0,'2026-04-25 21:06:05'),(7,2,'京剧有创新剧目吗',1,'2026-04-25 21:10:21'),(8,2,'是的，京剧有许多创新剧目。例如《大唐贵妃》融合了交响乐和现代舞台技术，《曹操与杨修》在传统基础上深化人物心理刻画，还有《廉吏于成龙》《党的女儿》等新编历史剧和现代戏。这些剧目在保留京剧核心唱腔和表演程式的同时，引入新题材和表现手法，推动了京剧艺术的当代发展。',0,'2026-04-25 21:10:28'),(9,2,'党的女儿什么时候产生的',1,'2026-04-25 21:13:32'),(10,2,'《党的女儿》是现代京剧创新剧目，首演于1991年，由上海京剧院创作，改编自同名电影。该剧以革命历史为背景，融合传统京剧唱腔和现代舞台表现手法，讲述了共产党员在白色恐怖下坚持斗争的故事，成为新编京剧的代表作之一。',0,'2026-04-25 21:13:37'),(11,3,'非遗云肩古时候用作什么的',1,'2026-04-26 12:27:00'),(12,3,'云肩是中国传统服饰中的一种装饰性披肩，古时候主要用于礼仪场合，如婚嫁、节日或正式宴席。它既有实用功能，能保护衣领免受头油和灰尘污染，也蕴含吉祥寓意，常用刺绣图案象征富贵、长寿或幸福。云肩在明清时期尤为流行，是女性服饰的重要点缀，也体现身份和审美。如今，云肩作为非遗项目，更多用于文化展示和传统艺术传承。',0,'2026-04-26 12:27:08'),(13,3,'云肩起源于哪里',1,'2026-04-26 12:29:20'),(14,3,'云肩的起源可追溯至隋唐时期，最早见于敦煌壁画中的飞天形象，最初受佛教艺术和西域服饰影响。宋代时，云肩逐渐融入中原服饰，成为贵族女性的装饰。明清时期，云肩发展成熟，流行于民间，尤其在婚嫁等喜庆场合。其名称源于形似云朵或如意，象征吉祥。作为非遗，云肩的起源体现了多元文化融合的历史。',0,'2026-04-26 12:29:27');
/*!40000 ALTER TABLE `knowledge_messages` ENABLE KEYS */;
