INSERT INTO `travel_posts` VALUES (1,10011,'qwe','asd','服饰妆造','passed',NULL,'[\"https://travelate.oss-cn-wuhan-lr.aliyuncs.com/yayfolk/posts/1/1.jpg\"]','[\"服饰妆造\"]','public',0,0,0,'2026-03-28 18:46:03','2026-03-28 18:47:01',0,0,'en'),(2,10011,'福建游神——中式信仰美学','曾以为神明住在云端\n直到走入福建的旧街巷\n迎上这场盛大的流动——\n原来最深的信仰\n就落在人间烟火里\n-\n当鼓点从青石板路深处传来\n神将巍峨的身姿转过巷角\n华服璀璨，眉目庄严\n却又带着一丝“人间气”——\n会接过孩童手中的糖果\n会为长者的祈福微微颔首\n那一刻突然懂得：\n所谓信仰\n不是高高在上的仰望\n而是人与神之间\n这份无声却厚重的连接\n-\n福州游神主要集中在长乐区，从正月初一开始到二月中，几乎每天都有，我追的这场是规模zui大的厚福游神：\n📍福州市长乐区潭头镇厚福乡\n📆正月初十、正月二十六\n⏰08:00-次日凌晨','民俗节气','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\"]','[\"民俗节气\",\"非遗追年地图\",\"旅行中的非遗体验\",\"游神\",\"福建游神\",\"民俗\",\"新年\",\"春节\"]','public',1,9,0,'2026-03-28 19:49:45','2026-04-26 16:28:07',0,0,'zh'),(3,10011,'老祖宗肩上的“时尚单品” 火了上千年','一抹云霞落肩头，流转千年仍惊艳！\n云肩是中华民族服饰文化中历史悠久且独特的服饰瑰宝，既是古人“天人合一”的智慧凝结，更是东方美学的精神传承！\n云肩之美，在其极致工艺！\n✅ 形制考究：四合如意、柳叶式、八方云纹…每一片云肩的剪裁都暗含深意。四合如意象征“四方祥和”，柳叶式放射状纹样寓意“生命长青”，而八片垂云则对应传统节庆的平安祈愿 。\n✅ 纹样密码：石榴葡萄喻多子，蝙蝠葫芦兆福禄…云肩的刺绣每一针都承载着古人对生活的美好期许。\n✅ 工艺巅峰：立体剪裁贴合女子肩颈曲线，云肩针法竟有滚针、盘金等诸多针法，绣娘以线为笔，将四季花鸟、祥云瑞兽化作肩头画卷。\n传承与创新：让云肩走进日常\n如今，云肩不再只是博物馆的展品：中式婚纱、马面裙+云肩、毕业季学士服+云肩、巴黎奥运会体操服装等，现代日常服饰不断融入云肩这一传统元素，诠释出更多新中式可能。（图1-10源于大英博物馆；图11-17源于郑州博物馆）\n\n老祖宗肩上的“时尚单品” 火了上千年\n\n中国传统工艺振兴服务平台\n2025-04-21\n3292\n\n🪡八位掌灯人｜穿越千年女性非遗技艺图鉴\n\n元气小葫要早睡💤\n2025-12-17\n1198\n\n《探索100种东方美学》——㉙云肩\n\n言小柒MiaoMiao\n2025-07-15\n1840\n\n\n原味栗子（接稿版）\n2025-12-30\n1581\n\n时尚中国，非遗的fashion之路㈧\n\nShine耀\n2024-12-23\n7.9万\n\n一眼心动！藏在肩上的东方绝美“天空”✨\n\n云山有趣的非遗\n2025-12-06\n2.5万\n大家都在搜\n\n非遗文化服装\n\n中国十大非遗\n\n非遗服饰有哪些\n\n非遗拟人化绘画\n\nTHE SEA LIFE×傣锦：将热带生态景象织在身上\n\n非遗Plus\n2025-07-31\n547\n\n「锦序东方」服装效果图分享\n\n钰榕设计（约稿中）\n01-28\n199\n\n聆听传统美学｜非遗醒狮\n\n你说天空很美丽\n01-14\n233\n\n这不是国外大牌高定！\n\n毛豆\n2025-12-12\n3.6万\n\n一刀一剪一世界——带你领略非遗的魅力(02)\n\nAIGC杨太医\n2025-08-01\n703\n\n服设系列—非遗\n\n张小花花老师\n2025-03-24\n1057\n\n非遗服饰服装分层设计图\n\n漓月\n2025-12-12\n14\n\n🔥中国国际时装周｜非遗服饰文化惊艳秀场\n\n遗韵云游\n2025-12-09\n144\n\n把非遗绒花穿身上，那该有多美？\n\n宁心如\n02-13\n11.4万\n大家都在搜\n\n中国传统非遗服装\n\n非遗人物绘画素材\n\n非遗服饰图片\n\n非遗文化主题衣服\n\n广艺/毕业设计/把非遗穿身上\n\n一只小馒头\n2025-04-11\n2106\n发现\n直播\n发布\n通知\n我\n×\n拖拽到此处\n图片将完成下载\n由Fitkun图片批量下载提供\n\n中国传统工艺振兴服务平台\n关注\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n1/17\n老祖宗肩上的“时尚单品” 火了上千年\n一抹云霞落肩头，流转千年仍惊艳！\n云肩是中华民族服饰文化中历史悠久且独特的服饰瑰宝，既是古人“天人合一”的智慧凝结，更是东方美学的精神传承！\n云肩之美，在其极致工艺！\n✅ 形制考究：四合如意、柳叶式、八方云纹…每一片云肩的剪裁都暗含深意。四合如意象征“四方祥和”，柳叶式放射状纹样寓意“生命长青”，而八片垂云则对应传统节庆的平安祈愿 。\n✅ 纹样密码：石榴葡萄喻多子，蝙蝠葫芦兆福禄…云肩的刺绣每一针都承载着古人对生活的美好期许。\n✅ 工艺巅峰：立体剪裁贴合女子肩颈曲线，云肩针法竟有滚针、盘金等诸多针法，绣娘以线为笔，将四季花鸟、祥云瑞兽化作肩头画卷。\n传承与创新：让云肩走进日常\n如今，云肩不再只是博物馆的展品：中式婚纱、马面裙+云肩、毕业季学士服+云肩、巴黎奥运会体操服装等，现代日常服饰不断融入云肩这一传统元素，诠释出更多新中式可能。\n\n你喜欢什么样的云肩造型呢？评论区留言~','服饰妆造','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/5.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/6.jpg\"]','[\"服饰妆造\",\"非遗\",\"东方美学\",\"云肩\",\"大英博物馆\",\"郑州博物馆\",\"传统服饰\"]','public',1,3,0,'2026-03-28 19:53:18','2026-04-26 16:28:10',0,0,'zh'),(4,10011,'唐三彩','釉色承千年，匠心照古今——洛阳唐三彩的非遗传承与时代新生\n在中华文明的璀璨星河中，洛阳唐三彩是一颗独特的星辰。它诞生于盛唐的沃土，以绚烂釉色、恢弘气势，成为那个时代的文化图腾；它历经千年岁月洗礼，在传承与创新的交织中，依然焕发着蓬勃生机，成为连接古今的文化桥梁。\n缘起盛唐：时代风骨孕育的艺术瑰宝\n唐三彩的诞生，是历史的必然。盛唐时期，洛阳作为十三朝古都，既是政治经济中心，也是丝绸之路的东方枢纽。东西方文化在此碰撞交融，为艺术创作注入了多元灵感\n工匠们以细腻的高岭土为胎，以金属氧化物为着色剂，经“制胎—施釉—烧制”三道核心工序，在窑火中完成一场“色彩的魔术”。不同于传统陶瓷的单一釉色，唐三彩的釉料在高温下自由流淌，红如丹砂、绿似翡翠、黄若蜜蜡，交融处形成的“流釉”效果，如云雾缭绕、如霞光漫卷，尽显盛唐的豪迈与浪漫。\n从皇室贵族的陪葬重器，到文人雅士的赏玩之物，唐三彩的题材无一不展现着盛唐的社会风貌与精神气度。它不仅是陶瓷艺术的巅峰，更是大唐盛世的“立体史书”。\n守正创新：非遗传承人的“破局”之路\n时光流转，盛唐落幕，但唐三彩的窑火并未熄灭。然而，在现代工业的冲击下，这门古老技艺曾一度面临“无人传承、无人问津”的困境。直到一批非遗传承人的出现，用“守正”筑牢根基，用“创新”开拓未来。\n“守正”是对古法工艺的敬畏。传承人李松茂坚守“手工制胎、手工施釉、柴窑烧制”的传统，每一件作品都要经过数十道工序，从陶土筛选到釉料调配，从入窑温度到烧制时间，都严格遵循古法。“柴窑的火性是电窑替代不了的，只有这样，才能烧出唐三彩独有的温润质感。”李松茂的话，道出了匠人的坚守。\n“创新”是与时代的对话。年轻传承人将唐三彩的经典元素与现代审美结合，推出了一系列文创产品：将三彩马做成小巧玲珑的车载摆件，把釉色纹样印在笔记本上甚至开发出“唐三彩DIY体验套装”，让消费者亲手感受施釉的乐趣。\n文化出海：千年釉色讲述中国故事\n如今，洛阳唐三彩已不再是中国的“文化瑰宝”，更成为世界了解中国的“文化名片”。在海外展出时，唐三彩马的矫健、乐伎俑的灵动，让外国观众惊艳于中国古代艺术的魅力；非遗传承人带着技艺走出国门，让世界看见中国匠心。\n从盛唐的窑火到如今的国际舞台，从博物馆的陈列品到日常的文创产品，洛阳唐三彩的传承之路是中国非遗文化发展的缩影。它用绚烂的釉色，诉说着中华文明的博大精深；用不变的匠心，诠释着文化传承的力量。','美术造物','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\"]','[\"美术造物\"]','public',1,10,0,'2026-03-28 19:58:05','2026-04-26 16:28:11',0,0,'zh'),(5,10011,'傩戏|中国硬核非遗','傩戏起源于商周时期的驱傩仪式，最初是古人通过歌舞祭祀驱鬼逐疫、祈福纳吉的宗教活动。汉代后逐渐融入娱人成分，宋代受民间歌舞影响发展为傩戏，元代至明清时期与地方戏曲融合，形成多样化流派。其历史可追溯至先秦的巫歌傩舞，被誉为“中国戏剧活化石”。\n	\n表演形式\n面具文化：演员佩戴木质或丝质面具（称“脸子”），造型夸张狰狞，直观区分角色性格，如贵州德江傩戏的面具多达上百种。\n宗教仪式融合：演出分“开坛”“开洞”“闭坛”三阶段，与祭祀活动一体，如湖北恩施傩戏需杀鸡请神、烧纸祭祖。\n傩技绝活：包含喷火、上刀梯、过火海等惊险技艺，体现原始巫术色彩。\n	\n音乐与剧目\n音乐以打击乐为主（锣、鼓、钹），辅以山歌、佛道乐曲，唱腔粗犷，多采用一唱众和形式。\n	\n剧目分三类：\n正戏：如《仙姑送子》《发五猖》，宗教色彩浓厚；\n傩堂小戏：如《采香》《陈州放粮》，娱乐性强；\n外台戏：吸收民间故事的《孟姜女》《三国演义》等。\n	\n傩戏主要分布于西南及长江流域，因地域文化差异形成多种流派：\n1.恩施傩戏（湖北）：分“傩愿戏”与“坛傩”，前者融入花鼓戏技巧，后者保留明代祭祖仪式，面具制作工艺独特。\n2.池州傩戏（安徽）：以宗族为单位演出，每年春秋两祭，保留《刘文龙》等古剧目，被誉为“无傩不成村”。\n3.侗族傩戏“咚咚推”（湖南）：舞蹈以“三角形”步伐模拟耕牛动作，剧目融合侗族生活与三国故事。\n4.德江傩堂戏（贵州）：被称为“中国戏剧活化石”，完整保留汉代傩仪传统，表演包含复杂法事。\n5.武安傩戏（河北）：具宋代宫廷傩遗风，角色“掌竹”为宋金杂剧引戏人遗存。','戏曲演绎','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/5.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/6.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/7.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/8.jpg\"]','[\"非遗\",\"傩戏\",\"非物质文化遗产\",\"非遗传承\",\"传统文化\",\"恩施傩戏\",\"池州傩戏\",\"戏曲演绎\",\"美术造物\"]','public',1,5,0,'2026-03-28 20:01:41','2026-04-26 16:28:14',0,0,'zh'),(6,10011,'以针为笔，以丝为墨，绣出江南的呼吸','苏绣，源于江苏苏州一带，以其独特的艺术魅力和精湛技艺位居“四大名绣”之首，素有“精、细、雅、洁”之称，并于2006年入选国家级非物质文化遗产。\n艺术特色：\n苏绣的灵魂在于“平、齐、细、密、匀、顺、和、光”八字。其最显著的特点是 “精微雅致” 。绣工们常将一根头发丝般粗细的丝线劈成更细的1/16甚至1/32来进行创作，使作品达到“不见针线痕迹，只觉画面生动”的境界。\n代表技艺：\n双面绣是苏绣皇冠上的明珠。绣娘们在同一块底料上，一次施针，正反两面却呈现出构图完整、针法相同而画面可能不同的完美图案，令人拍案叫绝。代表作《猫》更是将这一技艺发挥到极致，丝线天然的光泽将小猫蓬松的毛发、灵动的眼神表现得栩栩如生。\n文化内涵：\n苏绣深受吴地文化的熏陶，作品题材多取自江南文人画，充满诗情画意。它不仅是技艺的展现，更是江南水乡温婉、灵动、典雅气质的集中体现，是流动在指尖上的姑苏风情。','织物手工','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/5.jpg\"]','[\"织物手工\",\"非遗文化\",\"苏绣\",\"刺绣\"]','public',1,24,1,'2026-03-28 20:04:27','2026-04-26 18:54:06',0,0,'zh'),(7,10011,'认识一个非物质文化遗产——苗绣','⭐️起源\n贵州苗绣，一部用针线书写的民族史诗。苗绣起源可回溯到上古时期，与古代濮人的雕题文身有着千丝万缕的联系。彼时，随着濮人后裔南蛮掌握蚕桑技术，雕题文身逐渐演变为“描” ，待骨针、铜针出现，挑花和织花工艺应运而生。战国时期，苗绣正式在苗族服饰上崭露头角。\n元明清时期，因各支系苗民以不同动物为图腾，苗绣纹样风格各异，氏族间的交流又促使苗绣不断融合发展。\n2006年5月20日，贵州苗绣被列为国家级非物质文化遗产，遗产编号为Ⅶ-22。近年来，不断创新，融入现代设计与时尚产业，在国际舞台大放异彩，实现传承与发展的新跨越 。\n⭐️价值\n苗族没有传统意义上的文字，苗绣充当了“史书”角色。绣品中大量的神话传说、英雄故事、迁徙历程等图案，记录着苗族起源、发展轨迹，承载民族记忆与文化基因，像蝴蝶妈妈传说绣样，展现苗族独特创世观。\n此外，苗绣针法极为丰富，有平绣、辫绣、缠绣等几十种，每种针法呈现不同肌理质感 。色彩搭配大胆热烈，多运用红、黄、蓝等对比强烈的原色，形成鲜明视觉冲击，几何纹、动植物纹等图案造型夸张抽象，充满想象力与艺术感染力，具有极高的艺术价值。','织物手工','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/5.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/6.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\"]','[\"织物手工\",\"苗绣\"]','public',1,14,0,'2026-03-28 22:33:59','2026-04-26 16:28:20',0,0,'zh'),(8,10000,'abc','血色玛丽','服饰妆造','rejected','空','[]','[]','public',1,4,0,'2026-03-29 14:07:51','2026-03-29 14:49:24',0,0,'zh'),(9,10000,'abc','血色玛丽','服饰妆造','deleted',NULL,'[\"https://travelate.oss-cn-wuhan-lr.aliyuncs.com/yayfolk/posts/9/1.png\"]','[]','public',0,22,1,'2026-03-29 14:08:24','2026-04-05 18:34:26',0,1,'zh'),(10,10047,'加我wx','wx:874832797','服饰妆造','rejected','Rule blocked: Contains prohibited contact, advertising, or banned keywords','[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\"]','[]','public',1,0,0,'2026-03-29 14:57:27','2026-04-26 16:28:20',0,0,'en'),(11,10047,'毒品','新样式','服饰妆造','rejected','AI blocked: Text rejected: 不合规 ; 存在暴恐违禁不合规 | []','[\"https://te3ceeisz.hn-bkt.clouddn.com/1.webp\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.webp\"]','[]','public',1,2,0,'2026-03-29 15:02:26','2026-04-26 16:28:21',0,0,'zh'),(12,10011,'非遗珍宝｜点翠：千年不褪色的蓝','点翠，一项被誉为“首饰工艺绝唱”的国家级非物质文化遗产，以翠羽为墨，金银为骨，在方寸之间勾勒出千年不褪的华彩。它曾是帝王凤冠上的璀璨星辰，如今虽渐隐于时光，却仍是东方美学中一抹无法复制的幽蓝梦境。\n✨ 精工细作，巧夺天工\n点翠工艺的极致，在于“以羽为画”的匠心。工匠需先将金、银片捶揲成底托，再用金丝焊出图案轮廓，形成“嵌羽之槽”。随后，取翠鸟颈间最莹润的羽绒，以特制胶液轻贴于金属胎底。羽丝细软如尘，却需排列得密不透风，方能在光下流转出湖面波光般的幻彩。最后缀以珍珠、翡翠、珊瑚等宝玉石，方成一件雍容典雅的珍品。正如古籍所载：“虽无宝石炫亮，却自有一种艳丽拙朴之美。”\n👑 千年传承，宫廷绝色\n点翠工艺始于汉代，盛于乾隆。昔日的帝王衮服、皇后凤冠，皆以翠羽为饰，历经岁月仍鲜艳如初。一只翠鸟仅能取零星羽绒，修复一顶明代凤冠竟需十万翠羽，其珍贵可见一斑。这项工艺不仅象征着古代匠人的智慧，更承载着东方饰品对细节的执着——以工艺的精细、含蓄之美，诠释“富丽堂皇”的真正内涵。\n🌿 非遗新生，以今承古\n如今，翠鸟已成保护动物，传统点翠逐渐被孔雀羽、染绸等代用品取代。但这项工艺的生命力并未消逝——现代匠人以创新手法延续着点翠的魂韵，让这份“幽蓝幻彩”在当代首饰中重焕生机。非遗的点翠，不再是羽与金的简单结合，而是对千年美学的敬畏与传承。\n点翠的蓝，是时光浸染的诗意，更是工匠指尖流淌的星河。愿这份“永不褪色”的浪漫，能被更多人看见、铭记。','服饰妆造','passed',NULL,'[\"https://te3ceeisz.hn-bkt.clouddn.com/1.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/2.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/3.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/4.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/5.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/6.jpg\", \"https://te3ceeisz.hn-bkt.clouddn.com/7.jpg\"]','[\"点翠\",\"非遗传承\",\"东方美学\",\"传统工艺美学\"]','public',1,10,1,'2026-03-30 15:51:34','2026-04-26 16:28:24',0,0,'zh'),(13,10000,'yayfolk','test','服饰妆造','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/13/1.jpg\"]','[\"服饰妆造\"]','public',1,1,0,'2026-04-26 17:44:33','2026-04-26 17:44:44',0,0,'en');
